contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: send a ticket payment amount and then assert that pot is not forced to zero for all executions
    // inputs: payAmount must equal C.TICKET_AMOUNT(), and caller must hold enough balance to send it
    function runTest(uint payAmount) public payable {
        require(payAmount == c.TICKET_AMOUNT());
        require(address(this).balance >= payAmount);

        // record pot before play
        uint potBefore = c.pot();

        // perform the play that may or may not reset the pot depending on contract behavior
        c.play{value: payAmount}();

        // observe pot after play
        uint potAfter = c.pot();

        // GENERAL ASSERTION: it must be possible that potAfter equals potBefore + payAmount (i.e., pot was not forcibly reset)
        // This holds on original P because when random != 0 the transfer-path is skipped and pot increases by payAmount.
        // It is violated by mutant M which always resets pot to 0, making potAfter never equal potBefore + payAmount.
        assert(potAfter == potBefore + payAmount);
    }

    // allow contract to receive Ether so tests can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint public __snap;
    bool public __obsd;

    constructor(C _c) { c = _c; }

    // We take the ticket amount as a parameter and send it to c.play
    function run(uint amount) public payable {
        require(msg.value == 0); // ensure no accidental Ether is used from msg.value
        // must have enough balance to forward
        require(address(this).balance >= amount);
        // precondition: caller must send exactly the ticket amount to trigger play
        // but we don't know TICKET_AMOUNT here, so require amount > 0
        require(amount > 0);

        // Call play with value amount. The DIFFERENCE between original and mutant
        // is observable during the external transfer inside play, so we capture
        // c.pot() in receive() when the contract receives Ether.
        // Make the external call that changes c's state
        c.play{value: amount}();

        // After the call, the mid-call observation was stored in __snap by receive().
        // General rule: on the original contract, the observed pot mid-call can equal
        // the previous pot + amount. We assert that the observed value equals at least amount.
        // This is a general property that holds on the original but is violated by the mutant
        // which always resets pot to 0 before transfers causing mid-call pot to be 0.
        assert(__obsd && __snap >= amount);
    }

    receive() external payable {
        // Observe c.pot() MID-call. Only capture once.
        if (!__obsd) {
            __obsd = true;
            __snap = c.pot();
        }
    }
}

