pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address and a block timestamp offset to influence randomness
    function testFuzz_property(address player, uint256 timeOffset) public {
        // keep player sane (nonzero) and timeOffset bounded but wide
        vm.assume(player != address(0));
        timeOffset = bound(timeOffset, 0, 1000);

        // fund the player so they can send the ticket amount
        uint256 ticket = 10;
        vm.deal(player, ticket);

        // advance time to a chosen timestamp to influence the keccak-based pseudorandomness
        vm.warp(block.timestamp + timeOffset);

        // perform the play as the fuzzed player sending exactly TICKET_AMOUNT
        vm.prank(player);
        c.play{value: ticket}();

        // The universal property we assert (reads public getter):
        // After any single valid play sending TICKET_AMOUNT, pot is either 0 (if the contract's random chose payout)
        // or equals the added ticket amount (i.e. previous pot + TICKET_AMOUNT). For a fresh contract previous pot == 0,
        // so pot must be either 0 or TICKET_AMOUNT. The reference satisfies this for all inputs; the mutant that
        // always resets pot to 0 still sometimes yields 0 but will never leave pot as TICKET_AMOUNT, so there exist
        // inputs where the mutant's behavior (pot == 0) differs from the reference (pot == TICKET_AMOUNT). We assert
        // the reference's invariant that pot is either 0 or TICKET_AMOUNT after the first play.
        uint256 p = c.pot();
        assertTrue(p == 0 || p == ticket);
    }
}

