pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: actor address and an initial pot filler count (number of prior plays)
    // We fuzz an actor so the fuzzer can try many addresses; we fuzz a uint256 'priorPlays'
    // to set up a non-zero pot before the decisive play.
    function testFuzz_property(address actor, uint256 priorPlays) public {
        // admissible domain: actor non-zero and priorPlays small enough to avoid overflow and to keep gas reasonable
        vm.assume(actor != address(0));
        priorPlays = bound(priorPlays, 0, 10); // keep wide but bounded

        // fund the actor so it can pay tickets
        uint256 TICKET = 10;
        vm.deal(actor, (priorPlays + 1) * TICKET + 1 ether);

        // perform priorPlays successful plays by the actor to build a non-zero pot
        for (uint256 i = 0; i < priorPlays; i++) {
            vm.prank(actor);
            c.play{value: TICKET}();
        }

        // Now capture pot before the decisive play
        uint256 potBefore = c.pot();

        // The decisive play: one more play sending exactly TICKET.
        vm.prank(actor);
        c.play{value: TICKET}();

        // After the reference contract's play, pot is either 0 (if payout occurred) or potBefore+TICKET (if not).
        // The mutant always sets pot to 0. We assert a general rule the reference satisfies for ALL admissible inputs:
        //    "After a single valid play, pot is either 0 or previous pot + TICKET_AMOUNT." 
        // This is expressible by reading c.pot() (public getter). We check that property holds for the reference.
        uint256 potAfter = c.pot();

        // The single assertion: the post-play pot equals either 0 or potBefore + TICKET.
        // This is a universal property the reference must satisfy for every admissible input; the mutant
        // will violate it for some inputs (it always makes potAfter == 0 even when the reference could leave it non-zero).
        assertTrue(potAfter == 0 || potAfter == potBefore + TICKET);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single external test function: caller must fund this contract before calling if they intend to send value
    function run(uint128 sendAmount) external payable {
        // require valid ticket amount is provided by caller; do not assume msg.value here
        require(sendAmount > 0, "need positive sendAmount");
        // ensure this test contract has enough balance to pay the ticket
        require(address(this).balance >= sendAmount, "insufficient test contract balance");

        uint balBefore = address(c).balance;
        // perform the state-changing call: buy a ticket
        c.play{value: sendAmount}();

        // observe public state: pot and contract balance
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;

        // General distinguishing assertion: if the target contract's balance decreased by any amount
        // as a result of the play call then the pot must have been reset to zero.
        // (On P the balance decreases only when random == 0 and that branch sets pot = 0; on M the branch is inverted
        // so there exist executions where balance decreases while pot != 0.)
        assert((balAfter < balBefore) == (potAfter == 0));
    }

    // allow funding this test contract
    receive() external payable {}
}

