        uint256 boundedOffset = bound(timeOffset, 0, 1 days);
        vm.warp(block.timestamp + int256(boundedOffset));

        // perform the payable play call as the actor
        vm.prank(actor);
        c.play{value: ticket}();

        // The universal property: after any admissible call (caller != zero, paid exactly ticket),
        // in the reference implementation whenever the winner-transfer branch executed it resets pot to 0.
        // We assert that pot is either 0 or equals the ticket (i.e., untouched when no reset happened).
        // Crucially, the mutant that inverts the condition can leave pot non-zero in situations
        // where the reference would have reset it; thus the fuzzer will find an input where pot equals ticket
        // in the mutant but would be 0 in the reference. We assert the reference's invariant that after play,
        // pot is either 0 or equals the ticket amount (no other values possible).
