contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the block timestamp offset so the pseudorandom branch (based on block.timestamp and chain randomness)
    // can take either value; also fuzz the payer address to act as caller
    function testFuzz_property(uint64 tsOffset, address payer) public {
        // Keep payer non-zero
        vm.assume(payer != address(0));
        // Bound the offset to a reasonable range to avoid overflow when adding to block.timestamp
        uint256 bounded = uint256(tsOffset) % 100000;

        // Fund the payer and set the block timestamp to create different randomness
        vm.deal(payer, 1 ether);
        vm.warp(block.timestamp + bounded);

        // Caller pays exactly TICKET_AMOUNT (10 wei in contract) — use at least that amount
        uint256 payAmount = 10;
        vm.startPrank(payer);
        // perform the payable call; catch any reverts (shouldn't revert on correct input)
        try c.play{value: payAmount}() {
            // no-op
        } catch {
            // no-op
        }
        vm.stopPrank();

        // The universal property we assert: pot() is either 0 or equal to payAmount (in case no payout happened),
        // but crucially in the correct contract whenever the payout branch executes pot is reset to 0.
        // We assert a concrete, observable fact that the reference satisfies for all inputs: pot() is either 0 or >= 0
        // and specifically cannot be an unexpected leftover when a payout should have occurred. To keep this a single
        // getter-based assertion that the mutant will violate for some inputs, we assert that pot() is less than or
        // equal to payAmount (since the correct contract never accumulates more than the single ticket when run once
        // from zero pot and will reset to 0 if payout happens).

        // Single required assertion observing c:
        assertTrue(c.pot() <= payAmount);
    }
}

