contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract with just two plays: one to seed a non-zero pot, then the deciding play.
    // We take the ticket and fee as parameters so the verifier can reason generally.
    function runTest(uint ticketAmount, uint feeAmount, uint seedAmount, uint decideAmount) public payable {
        // Preconditions matching C's constants (ensures calls are valid and amounts represent the contract's expectations)
        require(seedAmount == ticketAmount);
        require(decideAmount == ticketAmount);
        require(ticketAmount > 0);
        // Ensure the test contract has enough ETH to make both calls
        require(address(this).balance >= seedAmount + decideAmount);

        // 1) First play to make pot > 0 (could win or lose, but if it wins pot becomes 0 again; still second play will observe behavior)
        c.play{value: seedAmount}();

        // Record contract balance before the deciding play
        uint before = address(c).balance;

        // 2) Deciding play: this is the call whose win branch should reset pot to 0 in original but not in mutant
        c.play{value: decideAmount}();

        // After the deciding play, if the winning branch executed, original sets pot to 0 so contract balance should be either 0 (if paid out) or reflect only fee retained.
        // We assert that the contract balance is strictly less than before + decideAmount (i.e., when win happened original emptied pot but mutant leaves pot non-zero making balance larger).
        // This observable comparison distinguishes the mutant: on P, a win leads to a smaller contract balance than the mutant which keeps pot.
        assert(address(c).balance <= before);
    }

    // Allow contract to receive ETH for funding test calls
    receive() external payable {}
}

