        // observe after
        uint afterPot = c.pot();
        uint afterBalance = address(c).balance;

        // General rule: after play either pot increased by ticket (no payout) or pot became zero (payout occurred)
        // Expressed without referring to randomness: afterPot == priorPot + ticket || afterPot == 0
        assert(afterPot == priorPot + ticket || afterPot == 0);
    }
    receive() external payable { }
}

