        vm.deal(address(this), C.TICKET_AMOUNT());
        vm.prank(address(rev));
        // send the ticket amount from the reverter: fund the reverter first
        vm.deal(address(rev), C.TICKET_AMOUNT());

        // record previous pot
        uint prevPot = c.pot();

        bool ok;
        try c.play{value: C.TICKET_AMOUNT()}() {
            ok = true;
        } catch {
            ok = false;
        }

