        // This reads the contract's public getter and is a single assertTrue as required.

        if (!ok) {
            // In the correct contract, when the player transfer reverts, the pot must be >= prevPot + TICKET_AMOUNT - FEE_AMOUNT
            // (i.e., the pot didn't get zeroed by premature pot = 0). Assert that property.
            assertTrue(c.pot() >= prevPot + C.TICKET_AMOUNT() - C.FEE_AMOUNT());
        } else {
            // If the call didn't revert we still assert a trivial true condition about pot to keep single assertTrue rule
            // but must read c; ensure pot is >= prevPot (since we added TICKET_AMOUNT and possibly paid out)
            assertTrue(c.pot() >= prevPot);
        }
    }
